// 命令参数与报价种类逐项匹配；任何其他kind、额外权利或旧冷回调均不能立遗赠。
#include "family_bequest_commands.hpp"
namespace hanmo::resident {
Outcome<FamilyBequestCommand> decode_family_bequest_command(const StableId& kind,const BoundaryValue& params){try{auto unique=validate_succession_json_unique(params);if(!unique.ok)return {false,{},unique.error};using namespace boundary;FamilyBequestCommand result;result.kind=kind;if(kind=="family_bequest_declare"){fields(params,{"beneficiary_actor_id","personal"},{},kind);result.beneficiary_actor_id=get_string(params,"beneficiary_actor_id",kind);auto selected=decode_succession_personal_selection(field(params,"personal",kind));if(!selected.ok)return {false,{},selected.error};result.selected=std::move(selected.value);if(result.beneficiary_actor_id.empty()||result.beneficiary_actor_id.size()>256)fail("InvalidBequestBeneficiary",kind);}else if(kind=="family_bequest_revoke"){fields(params,{"declaration_id"},{},kind);result.declaration_id=get_string(params,"declaration_id",kind);if(result.declaration_id.empty()||result.declaration_id.size()>256)fail("InvalidBequestDeclaration",kind);}else fail("UnknownFamilyBequestCommand",kind);return {true,std::move(result),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
Outcome<FamilyBequestQuote> preview_family_bequest_command(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,const FamilyBequestState& state,const FamilyBequestPlayerRead& player,const StableId& actor,const FamilyBequestCommand& command,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    if(!policy.enabled)return {false,{},common_failure("FamilyBequestProfileRequired").error};if(actor!=c.state().metadata.player_actor_id)return {false,{},common_failure("PlayerCommandAuthorityRequired").error};auto checked=validate_family_bequests(c,family,deaths,origin,policy,state,player,life4,people);if(!checked.ok)return {false,{},checked.error};FamilyBequestQuote quote;
    if(command.kind=="family_bequest_declare"){if(!command.declaration_id.empty())return {false,{},common_failure("InvalidFamilyBequestCommand").error};auto declared=preview_family_bequest_declaration(c,family,policy,actor,command.beneficiary_actor_id,command.selected,people);if(!declared.ok)return {false,{},declared.error};const auto* active=active_family_bequest(state,actor);if(active&&!family_bequest_source_equal(active->source,declared.value.source))return {false,{},common_failure("BequestAlreadyActive").error};quote.declaration=std::move(declared.value);}
    else if(command.kind=="family_bequest_revoke"){if(!command.beneficiary_actor_id.empty()||command.selected.money||!command.selected.goods.empty())return {false,{},common_failure("InvalidFamilyBequestCommand").error};auto revoked=preview_family_bequest_revocation(c,family,deaths,origin,policy,state,player,command.declaration_id,life4,people);if(!revoked.ok)return {false,{},revoked.error};quote.revocation=std::move(revoked.value);}
    else return {false,{},common_failure("UnknownFamilyBequestCommand").error};return {true,std::move(quote),{}};
}
Outcome<FamilyEffect> apply_family_bequest_command(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,FamilyBequestState& state,const FamilyBequestPlayerRead& player,const StableId& actor,const FamilyBequestCommand& command,const FamilyBequestQuote& quote,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    auto fresh=preview_family_bequest_command(c,family,deaths,origin,policy,state,player,actor,command,life4,people);if(!fresh.ok)return {false,{},fresh.error};Outcome<StableId> written;StableId beneficiary;
    if(command.kind=="family_bequest_declare"){if(!quote.declaration||quote.revocation||!fresh.value.declaration||!family_bequest_source_equal(quote.declaration->source,fresh.value.declaration->source))return {false,{},common_failure("StaleBequestDeclaration").error};beneficiary=quote.declaration->source.terms.beneficiary_actor_id;written=record_family_bequest(c,family,deaths,origin,policy,state,player,*quote.declaration,life4,people);}
    else{if(!quote.revocation||quote.declaration||quote.revocation->declaration_id!=command.declaration_id)return {false,{},common_failure("StaleBequestRevocation").error};const auto* declaration=state.declarations.find(command.declaration_id);if(!declaration)return {false,{},common_failure("UnknownBequestDeclaration").error};beneficiary=declaration->source.terms.beneficiary_actor_id;written=revoke_family_bequest(c,family,deaths,origin,policy,state,player,*quote.revocation,life4,people);}
    if(!written.ok)return {false,{},written.error};FamilyEffect effect;effect.success=true;effect.fact_id=written.value;effect.actor_id=actor;effect.heir_actor_id=beneficiary;effect.player_actor_id=c.state().metadata.player_actor_id;return {true,std::move(effect),{}};
}
Status validate_family_bequest_receipt(const FamilyBequestState& state,const StableId& kind,const StableId& actor,Integer tick,const FamilyEffect& effect){
    if(effect.success!=std::optional<bool>{true}||effect.already_completed||effect.code||effect.actor_id!=std::optional<StableId>{actor}||effect.player_actor_id!=std::optional<StableId>{actor}||!effect.fact_id||!effect.heir_actor_id)return common_failure("InvalidBequestReceipt");const FamilyBequestDeclaration* declaration=nullptr;Integer source_tick=-1;
    if(kind=="family_bequest_declare"){declaration=state.declarations.find(*effect.fact_id);if(declaration)source_tick=declaration->source.tick;}
    else if(kind=="family_bequest_revoke"){const auto* revoked=state.revocations.find(*effect.fact_id);if(revoked){declaration=state.declarations.find(revoked->declaration_id);source_tick=revoked->tick;if(revoked->donor_actor_id!=actor)return common_failure("BequestReceiptActorMismatch");}}
    return declaration&&source_tick==tick&&declaration->source.terms.donor_actor_id==actor&&declaration->source.terms.beneficiary_actor_id==*effect.heir_actor_id?common_success():common_failure("BequestReceiptSourceMismatch");
}
}
